SELECT COUNT(*)
FROM tb_post p

    p.deleted = 0
    AND p.status = 2

        AND p.user_id IN (
            SELECT followed_id FROM tb_user_follow WHERE follower_id = #{currentUserId}
        )


        AND p.user_id = #{currentUserId}


        AND p.tags LIKE CONCAT('%"', #{tag}, '"%')
